import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {cn} from "@/lib/utils";
import {getIcon} from "@/cards/icons";
import type {IconCardProps} from "./iconCard.types";

export const IconCardComponent = (
  props: PiCardProps<IconCardProps>,
): React.ReactNode => {
  const {iconName, iconProps, className, style, cardName} = props;

  return (
    <div className={cn(className)} style={style} data-pihanga={cardName}>
      {getIcon(iconName, iconProps)}
    </div>
  );
};

import {createCardDeclaration} from "@pihanga2/core";
import type React from "react";

export const ICON_CARD = "shad/icon";

export type IconCardProps = {
  /** Name of the icon as registered via `registerIcon` */
  iconName: string;

  /** Props forwarded to the icon element (e.g. size, strokeWidth) */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  iconProps?: Record<string, any>;

  /** Additional Tailwind classes applied to the wrapping `<div>` */
  className?: string;

  /** Inline styles applied to the wrapping `<div>` */
  style?: React.CSSProperties;
};

export const ShadIcon = createCardDeclaration<IconCardProps>(ICON_CARD);

import {registerCardComponent} from "@pihanga2/core";

import {IconCardComponent} from "./iconCard.component";
import {ICON_CARD} from "./iconCard.types";

export * from "./iconCard.types";

registerCardComponent({
  name: ICON_CARD,
  component: IconCardComponent,
});
